/**
 * Daily market & fiscal intelligence feed (BYOK rewrite).
 *
 * What changed and why:
 *  - No Firestore. The feed lives in localStorage on the device.
 *  - No Tavily server key. Live web search is not possible with a pure client-side
 *    BYOK setup, so the feed is generated by the user's own model and is clearly
 *    labelled as a MODEL ANALYSIS rather than live web monitoring. When you add a
 *    backend later, this is the single place to re-introduce a search provider.
 *  - Cached per {date, sector} so the feed costs one API call per day.
 */

import { intelligenceNewsSchema, type IntelligenceNews } from '../lib/schemas';
import {
  loadAiConfig,
  loadCustomBaseUrl,
  getProviderKey,
  resolveModel,
  sendChat,
} from './ai';

export { intelligenceNewsSchema };
export type { IntelligenceNews };

const CACHE_PREFIX = 'intel_';
const MAX_AGE_DAYS = 3;

function cacheKey(date: string, sector: string): string {
  return `${CACHE_PREFIX}${date}_${sector}`;
}

function readCache(date: string, sector: string): IntelligenceNews[] | null {
  try {
    const raw = localStorage.getItem(cacheKey(date, sector));
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) && parsed.length > 0 ? (parsed as IntelligenceNews[]) : null;
  } catch {
    return null;
  }
}

function writeCache(date: string, sector: string, news: IntelligenceNews[]): void {
  try {
    localStorage.setItem(cacheKey(date, sector), JSON.stringify(news));
  } catch {}
}

/** Stale entries from the last few days, used when today's generation fails. */
function readStale(sector: string): IntelligenceNews[] {
  const collected: IntelligenceNews[] = [];
  for (let d = 1; d <= MAX_AGE_DAYS; d++) {
    const dt = new Date();
    dt.setDate(dt.getDate() - d);
    const cached = readCache(dt.toISOString().split('T')[0], sector);
    if (cached) collected.push(...cached);
  }
  return collected;
}

const SYSTEM_PROMPT = `Tu es l'analyste économique de Libriwouô, spécialisé Burkina Faso / UEMOA.
Tu produis une veille fiscale, réglementaire et marché actionnable pour une PME.

RÈGLES STRICTES :
- Réponds UNIQUEMENT en français.
- Réponds UNIQUEMENT par un objet JSON valide : {"news":[ ... ]}
- Exactement 5 entrées, chacune avec : title (titre concis), excerpt (UNE phrase actionnable),
  category ("FISCAL" | "OPPORTUNITY" | "MARKET" | "TECH"), date ("YYYY-MM-DD"), url ("" si tu n'as
  pas de lien certain), targetSectors (["GLOBAL"] ou ["<secteur>"]).
- ZÉRO hallucination d'URL : mets "" quand tu n'es pas certain du lien.
- N'invente aucun texte, loi ou chiffre. Si tu n'es pas sûr d'une actualité récente,
  privilégie une analyse de fond sur le régime fiscal du secteur demandé.
- Aucun texte avant ou après le JSON.`;

function buildPrompt(sector: string, date: string): string {
  const sectorLabel = sector && sector !== 'Général' ? sector : 'PME';
  return `Date cible : ${date}
Secteur de l'entreprise : ${sectorLabel}

Génère 5 informations clés :
1. GLOBAL : réformes fiscales, décisions de la DGI, lois de finances Burkina Faso / UEMOA.
2. SPÉCIFIQUE au secteur "${sectorLabel}" : appels d'offres, subventions, évolutions de marché, innovation.`;
}

/** Parse + normalise the model output into validated news items. */
function parseNews(raw: string, sector: string, date: string): IntelligenceNews[] {
  let text = raw.replace(/```(?:json)?\s*/gi, '').replace(/```\s*/g, '');

  const firstBrace = text.indexOf('{');
  const firstBracket = text.indexOf('[');
  let start = firstBrace;
  if (firstBracket !== -1 && (firstBrace === -1 || firstBracket < firstBrace)) start = firstBracket;
  const lastBrace = text.lastIndexOf('}');
  const lastBracket = text.lastIndexOf(']');
  let end = lastBrace;
  if (lastBracket > end) end = lastBracket;

  if (start === -1 || end === -1 || end <= start) return [];
  text = text.substring(start, end + 1);

  let parsed: any;
  try {
    parsed = JSON.parse(text.trim());
  } catch (e) {
    console.warn('[Intelligence] JSON parse failed:', e);
    return [];
  }

  const rows: any[] = Array.isArray(parsed?.news) ? parsed.news : Array.isArray(parsed) ? parsed : [];
  const validCats = new Set(['FISCAL', 'OPPORTUNITY', 'MARKET', 'TECH']);

  const normalised = rows
    .filter((n: any) => n && typeof n.title === 'string' && typeof n.excerpt === 'string')
    .slice(0, 5)
    .map((n: any) => ({
      title: n.title,
      excerpt: n.excerpt,
      category: validCats.has(n.category) ? n.category : 'MARKET',
      date: typeof n.date === 'string' && n.date ? n.date : date,
      url: typeof n.url === 'string' ? n.url : '',
      targetSectors: Array.isArray(n.targetSectors) && n.targetSectors.length > 0
        ? n.targetSectors.map(String)
        : ['GLOBAL'],
    }));

  // Validate with Zod; drop anything malformed rather than persisting it.
  return normalised
    .map((item) => {
      const result = intelligenceNewsSchema.safeParse({ ...item, targetSectors: [sector, ...item.targetSectors] });
      return result.success ? result.data : null;
    })
    .filter((n): n is IntelligenceNews => n !== null);
}

export interface IntelligenceResult {
  news: IntelligenceNews[];
  /** Where the result came from — surfaced in the UI. */
  source: 'cache' | 'model' | 'stale' | 'none';
  /** Set when the feed is a model analysis, not live web monitoring. */
  notice?: string;
}

/**
 * Returns today's intelligence for a sector.
 * Never throws: falls back to cache → stale → empty.
 */
export async function fetchDailyIntelligence(sector: string = 'Général', force: boolean = false): Promise<IntelligenceNews[]> {
  const today = new Date().toISOString().split('T')[0];

  if (!force) {
    const cached = readCache(today, sector);
    if (cached) return cached;
  }

  try {
    const config = loadAiConfig();
    const apiKey = await getProviderKey(config.providerId);
    if (!apiKey) {
      const stale = readStale(sector);
      if (stale.length) return stale;
      return [];
    }

    const model = resolveModel(config, config.providerId);
    if (!model) return readStale(sector);

    const result = await sendChat({
      providerId: config.providerId,
      apiKey,
      model,
      baseUrlOverride: config.providerId === 'custom' ? loadCustomBaseUrl() || undefined : undefined,
      temperature: 0.3,
      maxTokens: 2500,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: buildPrompt(sector, today) },
      ],
    });

    const news = parseNews(result.text, sector, today);
    if (news.length === 0) return readStale(sector);

    writeCache(today, sector, news);
    return news;
  } catch (error) {
    console.warn('[Intelligence] generation failed:', error);
    return readStale(sector);
  }
}

/** Metadata for the UI: what the current feed represents. */
export async function getIntelligenceStatus(sector: string = 'Général'): Promise<IntelligenceResult> {
  const today = new Date().toISOString().split('T')[0];
  const cached = readCache(today, sector);
  if (cached) {
    return {
      news: cached,
      source: 'cache',
      notice: "Analyse générée par votre modèle IA — pas une veille web temps réel.",
    };
  }
  return { news: [], source: 'none', notice: "Aucune veille pour aujourd'hui. Actualisez pour la générer." };
}
